-- Deploy ff2b_db:price_licences to pg

BEGIN;

CREATE TABLE IF NOT EXISTS "license_type_prices" (
    -- Unique identifier of the price
    "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- License type id referencing license type table
    "license_type_id" INTEGER NOT NULL,
    -- Season ID referring to a season into the table seasons
    "season_id" SMALLINT NOT NULL,
    -- Amount of the license_type
    "amount" SMALLINT NOT NULL,
    -- Currency of the price
    "currency" CHAR(3) NOT NULL,

    CONSTRAINT "fk_license_type_prices_license_type_id_license_types_id"
    FOREIGN KEY ("license_type_id")
    REFERENCES "license_types"("id"),

    CONSTRAINT "fk_license_types_prices_season_id_seasons_id"
    FOREIGN KEY ("season_id")
    REFERENCES "seasons"("id")
);

COMMIT;
